"use client";
import { useNotifications } from "./hooks/useNotifications";
import { useSocketConnection } from "./hooks/useSocketConnection";
import { NotificationHeader } from "./Components/NotificationHeader";
import { NotificationCard } from "./Components/NotificationCard";
import { EmptyState } from "./Components/EmptyState";

import { useRef, useEffect } from "react";
import { useContacts } from "../contacts/hooks/useInfiniteQuery";
import { useVirtualizer } from "@tanstack/react-virtual";

import {
  QueryClient,
  QueryClientProvider,
  useInfiniteQuery,
} from "@tanstack/react-query";

import fetchServerPage from "./virtualization";

const queryClient = new QueryClient();

fetchServerPage(10, 0); // Pre-fetch first page

export default function NotificationsPage() {
  const { data, fetchNextPage, hasNextPage, isFetchingNextPage } =
    useContacts();
  const loadMoreRef = useRef<HTMLDivElement | null>(null);
  useEffect(() => {
    if (!hasNextPage) return;
    const el = loadMoreRef.current;
    if (!el) return;

    const observer = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) {
        fetchNextPage();
      }
    });

    observer.observe(el);
    return () => observer.disconnect();
  }, [hasNextPage, fetchNextPage]);

  const { notifications, handleMarkAsRead } = useNotifications();

  const { isConnected, showReconnectMessage, dismissReconnectMessage } =
    useSocketConnection();

  return (
    <QueryClientProvider client={queryClient}>
      <div className="space-y-6">
        <NotificationHeader
          isConnected={isConnected}
          showReconnectMessage={showReconnectMessage}
          onDismissReconnect={dismissReconnectMessage}
        />

        {/* Notifications List */}
        <div className="space-y-4">
          {notifications.length === 0 ? (
            <EmptyState />
          ) : (
            notifications.map((notification, index) => (
              <NotificationCard
                key={notification.id || `notification-${index}`}
                notification={notification}
                onMarkAsRead={handleMarkAsRead}
              />
            ))
          )}
        </div>
        <div
          ref={loadMoreRef}
          className="h-10 flex items-center justify-center"
        >
          {isFetchingNextPage
            ? "Loading more..."
            : hasNextPage
            ? "Scroll to load more"
            : "No more posts"}
        </div>
      </div>
    </QueryClientProvider>
  );
}
